/** `orders/{id}/shipments` payload — the list is sometimes wrapped in a paginated envelope. */
export interface ShipmentsResponse {
    data?: Shipment[] | {
        data?: Shipment[];
    };
}
export interface ShipmentProduct {
    name: string;
    quantity?: number;
    image?: string;
}
/** Shipment as returned by `orders/{id}/shipments` — field names match the API. */
export interface Shipment {
    id?: number | string;
    number?: string | null;
    name?: string;
    logo?: string;
    website?: string | null;
    tracking_url?: string | null;
    products?: ShipmentProduct[];
}
